-- Postgres baseline schema for ivcrush: the CURRENT schema, version 8.
--
-- ⚠️ Maintained by hand since 2026-09-13, and kept equal to production.
-- Until then this file was generated from the SQLite database by
-- 2.0/scripts/generate_pg_ddl.py, whose input was deleted when SQLite was
-- retired, so it cannot be regenerated. Every test fixture is built from it
-- (common/pgtesting.baseline_ddl), which is why it tracks the live schema
-- rather than the cutover snapshot.
--
-- The rule, enforced by MigrationManager's BASELINE_VERSION:
--   a schema change is a migration in 2.0/sql/migrations/NNN_name.sql AND the
--   same change here AND BASELINE_VERSION = NNN, in one commit.
-- Verify equivalence by building a database from this file and diffing its
-- catalog digest against production (see the Postgres server notes, "Schema
-- drift check"). A row count cannot see a type or a constraint.
--
-- Cut and deliberately absent: backtest_runs, backtest_trades, cache, iv_log, rate_limits, ticker_metadata.

CREATE TABLE "analysis_log" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "timestamp" timestamptz NOT NULL,
    "ticker" text NOT NULL,
    "earnings_date" date NOT NULL,
    "expiration" date NOT NULL,
    "implied_move_pct" double precision NOT NULL,
    "historical_intraday_mean_pct" double precision,
    "vrp_intraday_ratio" double precision,
    "recommendation" text NOT NULL,
    "consistency_score" double precision,
    "vix_level" double precision,
    "vix_regime" text,
    "raw_analysis" text,
    "historical_close_mean_pct" double precision,
    "vrp_close_ratio" double precision,
    "term_slope_ratio" double precision,
    "recent_move_up_count" bigint,
    "recent_move_qtrs" bigint,
    "source" text,
    "vrp_convention" text NOT NULL,
    CONSTRAINT analysis_log_recommendation_check
        CHECK (recommendation IN ('excellent', 'good', 'marginal', 'skip')),
    CONSTRAINT analysis_log_vix_regime_check
        CHECK (vix_regime IN ('very_low', 'low', 'normal', 'normal_high',
                              'elevated', 'elevated_high', 'high', 'extreme')),
    CONSTRAINT analysis_log_source_check
        CHECK (source IN ('analyze', 'scan', 'whisper', 'ticker')),
    CONSTRAINT analysis_log_vrp_convention_check
        CHECK (vrp_convention IN ('intraday', 'close')),
    CONSTRAINT analysis_log_graded_ratio_present
        CHECK ((vrp_convention = 'intraday' AND vrp_intraday_ratio IS NOT NULL)
            OR (vrp_convention = 'close' AND vrp_close_ratio IS NOT NULL))
);
CREATE INDEX idx_analysis_recommendation ON analysis_log(recommendation);
CREATE INDEX idx_analysis_regime ON analysis_log(vix_regime);
CREATE INDEX idx_analysis_ticker_timestamp ON analysis_log (ticker, "timestamp" DESC);
CREATE INDEX idx_analysis_timestamp ON analysis_log(timestamp);

CREATE TABLE "bias_predictions" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ticker" text NOT NULL,
    "earnings_date" date NOT NULL,
    "expiration" date NOT NULL,
    "stock_price" double precision NOT NULL,
    "predicted_at" timestamptz NOT NULL,
    "skew_atm" double precision NOT NULL,
    "skew_curvature" double precision NOT NULL,
    "skew_strength" text NOT NULL,
    "slope_atm" double precision NOT NULL,
    "directional_bias" text NOT NULL,
    "bias_strength" bigint NOT NULL,
    "bias_confidence" double precision NOT NULL,
    "r_squared" double precision NOT NULL,
    "num_points" bigint NOT NULL,
    "actual_move_pct" double precision,
    "actual_gap_pct" double precision,
    "actual_direction" text,
    "prediction_correct" boolean,
    "validated_at" timestamptz,
    "compound_risk_active" boolean,
    "r_slp_30" double precision,
    "fused_bias" text,
    "trr_level" text,
    "sizing_alarm" boolean,
    UNIQUE(ticker, earnings_date),
    CONSTRAINT bias_predictions_directional_bias_check
        CHECK (directional_bias IN ('strong_bearish', 'bearish', 'weak_bearish', 'neutral',
                                    'weak_bullish', 'bullish', 'strong_bullish')),
    CONSTRAINT bias_predictions_fused_bias_check
        CHECK (fused_bias IN ('strong_bearish', 'bearish', 'weak_bearish', 'neutral',
                              'weak_bullish', 'bullish', 'strong_bullish')),
    CONSTRAINT bias_predictions_skew_strength_check
        CHECK (skew_strength IN ('smile', 'inverse_smile', 'smirk')),
    CONSTRAINT bias_predictions_trr_level_check
        CHECK (trr_level IN ('LOW', 'NORMAL', 'HIGH')),
    CONSTRAINT bias_predictions_actual_direction_check
        CHECK (actual_direction IN ('UP', 'DOWN', 'FLAT'))
);
CREATE INDEX idx_bias_date ON bias_predictions(earnings_date);
CREATE INDEX idx_bias_strength ON bias_predictions(bias_strength);
CREATE INDEX idx_bias_validated ON bias_predictions(validated_at);

CREATE TABLE "earnings_calendar" (
    "ticker" text,
    "earnings_date" date,
    "timing" text NOT NULL CHECK(timing IN ('BMO', 'AMC', 'DMH', 'UNKNOWN')),
    "confirmed" boolean DEFAULT false,
    "created_at" timestamptz DEFAULT now(),
    "updated_at" timestamptz DEFAULT now(),
    "last_validated_at" timestamptz,
    PRIMARY KEY (ticker, earnings_date)
);
CREATE INDEX idx_earnings_date_ticker ON earnings_calendar(earnings_date, ticker);

-- The three move percentages are GENERATED from the row's prices and cannot
-- be written. They are last because migration 2 re-added them, and column
-- order here matches production.
CREATE TABLE "historical_moves" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ticker" text NOT NULL,
    "earnings_date" date NOT NULL,
    "prev_close" double precision NOT NULL,
    "earnings_open" double precision NOT NULL,
    "earnings_high" double precision NOT NULL,
    "earnings_low" double precision NOT NULL,
    "earnings_close" double precision NOT NULL,
    "volume_before" bigint,
    "volume_earnings" bigint,
    "created_at" timestamptz DEFAULT now(),
    "pre_earnings_straddle_pct" double precision,
    "ern_iv_effect" double precision,
    "intraday_move_pct" double precision NOT NULL
        GENERATED ALWAYS AS ((earnings_close - earnings_open) / earnings_open * 100) STORED,
    "gap_move_pct" double precision NOT NULL
        GENERATED ALWAYS AS ((earnings_open - prev_close) / prev_close * 100) STORED,
    "close_move_pct" double precision NOT NULL
        GENERATED ALWAYS AS ((earnings_close - prev_close) / prev_close * 100) STORED,
    UNIQUE(ticker, earnings_date),
    CONSTRAINT historical_moves_prices_positive CHECK (prev_close > 0 AND earnings_open > 0)
);
CREATE INDEX idx_moves_date ON historical_moves(earnings_date);

CREATE TABLE "iv_history" (
    "ticker" text,
    "snapshot_date" date,
    "iv30d" double precision,
    "hv20d" double precision,
    "atm_strike" double precision,
    "expiration" date,
    "dte" bigint,
    "source" text DEFAULT 'tradier',
    PRIMARY KEY (ticker, snapshot_date)
);

CREATE TABLE "job_status" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "date" date NOT NULL,
    "job_name" text NOT NULL,
    "status" text NOT NULL,
    "updated_at" timestamptz NOT NULL,
    UNIQUE(date, job_name),
    CONSTRAINT job_status_status_check CHECK (status IN ('running', 'success', 'error'))
);

CREATE TABLE "position_limits" (
    "ticker" text PRIMARY KEY,
    "max_contracts" bigint DEFAULT 100,
    "max_notional" double precision DEFAULT 50000,
    "tail_risk_ratio" double precision,
    "tail_risk_level" text,
    "avg_move" double precision,
    "max_move" double precision,
    "num_quarters" bigint,
    "notes" text,
    "last_updated" timestamptz DEFAULT now(),
    "iv_rank_1y" double precision,
    "iv_pct_1y" double precision,
    "iv30d" double precision,
    "hv20d" double precision,
    "abs_avg_ern_mv" double precision,
    "orats_implied_ern_mv" double precision,
    "fcst_ern_iv_effect" double precision,
    "iee_earn_effect" double precision,
    "r_slp_30" double precision
);

CREATE TABLE "schema_migrations" (
    "version" bigint PRIMARY KEY,
    "name" text NOT NULL,
    "applied_at" timestamptz NOT NULL,
    "checksum" text
);

CREATE TABLE "sentiment_cache" (
    "ticker" text,
    "date" date,
    "source" text NOT NULL,
    "sentiment" text NOT NULL,
    "cached_at" timestamptz NOT NULL,
    PRIMARY KEY (ticker, date)
);

-- sentiment_direction has no CHECK on purpose: an LLM fills it, and /council
-- writes skew levels. See migration 2, section 8.
CREATE TABLE "sentiment_history" (
    "ticker" text,
    "earnings_date" date,
    "collected_at" timestamptz NOT NULL,
    "source" text NOT NULL,
    "sentiment_text" text NOT NULL,
    "sentiment_score" double precision,
    "sentiment_direction" text,
    "vrp_ratio" double precision,
    "implied_move_pct" double precision,
    "actual_move_pct" double precision,
    "actual_direction" text,
    "prediction_correct" boolean,
    "trade_outcome" text,
    "updated_at" timestamptz,
    "move_contained" boolean,
    "trr_at_entry" double precision,
    "vrp_convention" text,
    PRIMARY KEY (ticker, earnings_date),
    CONSTRAINT sentiment_history_actual_direction_check
        CHECK (actual_direction IN ('UP', 'DOWN', 'FLAT')),
    CONSTRAINT sentiment_history_trade_outcome_check
        CHECK (trade_outcome IN ('WIN', 'LOSS', 'SKIP')),
    CONSTRAINT sentiment_history_vrp_convention_check
        CHECK (vrp_convention IN ('intraday', 'close')),
    CONSTRAINT sentiment_history_vrp_convention_with_ratio
        CHECK ((vrp_ratio IS NULL) = (vrp_convention IS NULL))
);
CREATE INDEX idx_sentiment_history_date ON sentiment_history(earnings_date);
CREATE INDEX idx_sentiment_history_outcome ON sentiment_history(trade_outcome);

-- Money is numeric(14,2): exact to the cent. Python reads it as float
-- (common.db.configure_types).
CREATE TABLE "strategies" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "symbol" text NOT NULL,
    "strategy_type" text NOT NULL CHECK(strategy_type IN ('SINGLE', 'SPREAD', 'IRON_CONDOR', 'STRANGLE', 'STOCK', 'WHEEL', 'CASH_SECURED_PUT', 'COVERED_CALL')),
    "acquired_date" date NOT NULL,
    "sale_date" date NOT NULL,
    "days_held" bigint,
    "expiration" date,
    "quantity" numeric,
    "net_credit" numeric(14,2),
    "net_debit" numeric(14,2),
    "gain_loss" numeric(14,2) NOT NULL,
    "is_winner" boolean NOT NULL,
    "earnings_date" date,
    "actual_move" double precision,
    "created_at" timestamptz DEFAULT now(),
    "trade_type" text CHECK(trade_type IN ('NEW', 'ROLL', 'REPAIR', 'ADJUSTMENT')),
    "parent_strategy_id" bigint,
    "campaign_id" text,
    "trr_at_entry" double precision,
    "position_limit_at_entry" bigint,
    "account_type" text NOT NULL DEFAULT 'TAXABLE',
    CONSTRAINT strategies_parent_strategy_id_fkey
        FOREIGN KEY (parent_strategy_id) REFERENCES strategies (id),
    CONSTRAINT strategies_account_type_check CHECK (account_type IN ('TAXABLE', 'IRA'))
);
CREATE INDEX idx_strategies_campaign ON strategies(campaign_id) WHERE campaign_id IS NOT NULL;
CREATE INDEX idx_strategies_earnings ON strategies(earnings_date);
CREATE INDEX idx_strategies_parent ON strategies(parent_strategy_id);
CREATE INDEX idx_strategies_symbol ON strategies(symbol);
CREATE INDEX idx_strategies_trade_type ON strategies(trade_type);
CREATE INDEX idx_strategies_trr ON strategies(trr_at_entry) WHERE trr_at_entry IS NOT NULL;
CREATE INDEX idx_strategies_type ON strategies(strategy_type);

CREATE TABLE "taco_log" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "timestamp" timestamptz NOT NULL,
    "mode" text NOT NULL,
    "direction" text,
    "spot" double precision,
    "drawdown_pct" double precision,
    "runup_z" double precision,
    "vix" double precision,
    "vix_spike" double precision,
    "vix_term_ratio" double precision,
    "event_date" date,
    "event_type" text,
    "event_rationale" text,
    "score" double precision,
    "tier" text,
    "recommendation" text,
    "cross_asset_count" bigint,
    "cross_asset_available" bigint,
    "cross_asset_detail" text,
    CONSTRAINT taco_log_mode_check CHECK (mode IN ('check', 'positions')),
    CONSTRAINT taco_log_tier_check CHECK (tier IN ('FULL', 'HALF', 'PILOT', 'SKIP')),
    CONSTRAINT taco_log_direction_check CHECK (direction IN ('CALL', 'PUT'))
);

CREATE TABLE "taco_positions" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "direction" text NOT NULL,
    "symbol" text NOT NULL,
    "contracts" bigint NOT NULL,
    "strike" double precision NOT NULL,
    "expiration" date NOT NULL,
    "premium_paid" numeric(14,2) NOT NULL,
    "entry_date" date NOT NULL,
    "event_date" date NOT NULL,
    "pre_event_high" double precision,
    "panic_low" double precision,
    "euphoria_high" double precision,
    "rip_base" double precision,
    "pre_event_vix" double precision,
    "status" text NOT NULL DEFAULT 'OPEN',
    "exit_date" date,
    "proceeds" numeric(14,2),
    "outcome_pnl" numeric(14,2),
    "rule_compliant" boolean NOT NULL DEFAULT true,
    "created_at" timestamptz NOT NULL,
    CONSTRAINT taco_positions_status_check CHECK (status IN ('OPEN', 'CLOSED')),
    CONSTRAINT taco_positions_direction_check CHECK (direction IN ('CALL', 'PUT'))
);

-- trade_journal_dedup is the /journal import's conflict target, and it must be
-- a CONSTRAINT: ON CONFLICT ON CONSTRAINT cannot name a plain unique index.
-- NULLS NOT DISTINCT makes two stock legs (NULL option_type and strike) collide.
CREATE TABLE "trade_journal" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "symbol" text NOT NULL,
    "acquired_date" date,
    "sale_date" date NOT NULL,
    "days_held" bigint,
    "option_type" text,
    "strike" double precision,
    "expiration" date,
    "quantity" numeric,
    "cost_basis" numeric(14,2) NOT NULL,
    "proceeds" numeric(14,2) NOT NULL,
    "gain_loss" numeric(14,2) NOT NULL,
    "is_winner" boolean NOT NULL,
    "term" text,
    "wash_sale_amount" numeric(14,2) DEFAULT 0,
    "earnings_date" date,
    "actual_move" double precision,
    "created_at" timestamptz DEFAULT now(),
    "strategy_id" bigint,
    "account_type" text NOT NULL DEFAULT 'TAXABLE',
    FOREIGN KEY ("strategy_id") REFERENCES "strategies" ("id"),
    CONSTRAINT trade_journal_dedup UNIQUE NULLS NOT DISTINCT
        (symbol, acquired_date, sale_date, option_type, strike, cost_basis, account_type),
    CONSTRAINT trade_journal_account_type_check CHECK (account_type IN ('TAXABLE', 'IRA')),
    CONSTRAINT trade_journal_option_type_check CHECK (option_type IN ('CALL', 'PUT')),
    CONSTRAINT trade_journal_term_check CHECK (term IN ('SHORT', 'LONG'))
);
CREATE INDEX "idx_trade_journal_earnings" ON trade_journal(earnings_date);
CREATE INDEX "idx_trade_journal_sale_date" ON trade_journal(sale_date);
CREATE INDEX "idx_trade_journal_strategy" ON trade_journal(strategy_id);

-- One trade placed in both accounts is one position (migration 5, 2026-09-15).
-- strategies holds a row per account, so a spread opened in the IRA and in
-- TAXABLE on the same day counted twice in every trade count and win rate --
-- ten pairs on 2026-09-15. Rows merge when symbol, strategy type, entry and exit
-- dates, expiration, legs (option type and strike, from trade_journal), earnings
-- date and parent all match: size and P&L are summed, and the win is decided on
-- the summed P&L. A second copy within one account pairs with the other
-- account's second copy, never with its own account. Every count, win rate and
-- average reads this view; per-account P&L still reads strategies.
CREATE VIEW "positions" AS
WITH legs AS (
    SELECT strategy_id,
           string_agg(DISTINCT option_type || ' ' || strike::text, ','
                      ORDER BY option_type || ' ' || strike::text) AS legs
    FROM trade_journal
    WHERE strategy_id IS NOT NULL AND option_type IS NOT NULL
    GROUP BY strategy_id
),
keyed AS (
    SELECT s.*, coalesce(l.legs, '') AS legs,
           row_number() OVER (
               PARTITION BY s.symbol, s.strategy_type, s.acquired_date, s.sale_date, s.expiration,
                            coalesce(l.legs, ''), s.earnings_date, s.parent_strategy_id, s.account_type
               ORDER BY s.id) AS copy
    FROM strategies s
    LEFT JOIN legs l ON l.strategy_id = s.id
)
SELECT min(id) AS id,
       array_agg(id ORDER BY id) AS strategy_ids,
       symbol,
       strategy_type,
       string_agg(account_type, '+' ORDER BY account_type) AS account_type,
       acquired_date,
       sale_date,
       min(days_held) AS days_held,
       expiration,
       sum(quantity) AS quantity,
       sum(net_credit) AS net_credit,
       sum(net_debit) AS net_debit,
       sum(gain_loss) AS gain_loss,
       sum(gain_loss) > 0 AS is_winner,
       earnings_date,
       min(actual_move) AS actual_move,
       min(trade_type) AS trade_type,
       parent_strategy_id,
       min(campaign_id) AS campaign_id,
       min(trr_at_entry) AS trr_at_entry,
       min(position_limit_at_entry) AS position_limit_at_entry,
       min(created_at) AS created_at,
       legs
FROM keyed
GROUP BY symbol, strategy_type, acquired_date, sale_date, expiration, legs, earnings_date,
         parent_strategy_id, copy;

-- Folds in scan_cache.db (11 rows, 6-day TTL). Rows are NOT migrated -- a TTL
-- cache refills itself within a day and copying it is pure ceremony.
CREATE TABLE "whisper_cache" (
    "cache_key"  text PRIMARY KEY,
    "payload"    jsonb NOT NULL,
    "expires_at" timestamptz NOT NULL
);
CREATE INDEX idx_whisper_cache_expires ON whisper_cache (expires_at);

-- Derived, recomputed weekly by refresh_risk_metrics.py; never migrated.
-- Sharpe/Sortino need net_campaigns()'s netting rule, which is not
-- expressible as a SQL aggregate (docs/SHARPE_ANALYSIS_2026-09.md section 2).
-- computed_at is nullable and has no DEFAULT (migration 8): it must be written
-- by the refresh that produced the row, so that a stalled weekly refresh shows
-- as a stale timestamp on the panel instead of an indistinguishable number.
CREATE TABLE "risk_metrics_snapshot" (
    "window_months" int PRIMARY KEY,
    "sharpe"        double precision,
    "sortino"       double precision,
    "n_months"      int,
    "computed_at"   timestamptz
);

-- Derived, recomputed weekly by refresh_rule_evidence.py; never migrated.
-- The band tallies four dashboard panels read. Exit timing needs
-- market_calendar's trading days and TRR needs tail_risk.py's ladder, neither
-- expressible in SQL without copying domain logic -- the same reasoning as
-- risk_metrics_snapshot above. band_order because band labels do not sort:
-- lexicographically 1-50 precedes 101-200 precedes 200+ precedes 51-100.
CREATE TABLE "rule_evidence_snapshot" (
    "dimension"       text NOT NULL,
    "cohort"          text NOT NULL,
    "band"            text NOT NULL,
    "band_order"      int NOT NULL,
    "trades"          int NOT NULL,
    "wins"            int NOT NULL,
    "pnl"             numeric(14,2),
    "avg_loss"        numeric(14,2),
    "median_quantity" double precision,
    "computed_at"     timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY ("dimension", "cohort", "band")
);
